// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address caller, uint256 value, bytes memory data) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        vm.assume(caller != address(this));
        vm.assume(caller != address(uint160(uint256(keccak256("owner")))));

        vm.assume(caller != address(this));

        value = bound(value, 0, 1 ether);

        vm.deal(address(c), 1 ether);

        bool ok;
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        try c.sendMoney(address(0xdead), value, data) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}
